import React, { useEffect, useState } from "react";
import { Modal, Form, Input, Select, Button, Message, Grid, Space, InputNumber } from '@arco-design/web-react';
import ajax from "@/utils/ajax";
import { IconDelete, IconArrowRise, IconArrowFall } from "@arco-design/web-react/icon";
import { EditMarkdown } from "@/components/markdown";

const { useForm } = Form;

interface CreateTemplateProps {
    visible: boolean;
    onClose: () => void;
    onSubmit: () => void;
    item: any;  // 当前AI 插件
}

const CreateTemplate = ({ visible, onClose, onSubmit, item }: CreateTemplateProps) => {
    const [form] = useForm();
    const [aiModels, setAiModels] = useState([]);

    const handleSubmit = () => {
        form.validate().then(values => {
            if (item) {
                ajax.post('/apijson/put', {
                    "PromptTemplate": {
                        ...values,
                        id: item.id,
                        content: JSON.stringify(values.content || {}),
                    }
                }).then(() => {
                    onSubmit();
                    Message.success('提示词模板创建成功');
                    onClose();
                })
            } else {
                ajax.post('/apijson/post', {
                    "PromptTemplate": {
                        ...values,
                        content: JSON.stringify(values.content || {})
                    }
                }).then(() => {
                    ajax.post('/deepseek/clear');   // 清除换车
                    onSubmit();
                    Message.success('提示词模板创建成功');
                    onClose();
                })
            }
        });
    };

    useEffect(() => {
        form.setFieldsValue(item);
    }, [])

    return (
        <Modal
            title={item ? "更新AI模板" : "新增AI模板"}
            visible={visible}
            onCancel={onClose}
            onOk={handleSubmit}
            style={{ width: 800 }}
        >
            <Form form={form} layout="vertical">
                <Form.Item
                    label="模板名称"
                    field="name"
                    rules={[{ required: true, message: '请输入模板名称' }]}
                >
                    <Input placeholder="例如：卡通头像生成" />
                </Form.Item>
                <Form.Item 
                    label="采样温度"
                    extra="0～2 温度越高，内容越随机"
                    field="content.temperature"
                >
                    <InputNumber placeholder="请输入" />
                </Form.Item>
                <Form.Item label="模版内容">
                    <Form.List
                        field='content.list'
                    >
                        {(fields, { add, remove, move }) => {
                            return (
                                <div>
                                    {fields.map((item, index) => {
                                        return (
                                            <Grid.Row key={index}>
                                                <Form.Item
                                                    field={item.field + '.role'}
                                                    style={{
                                                        width: 300,
                                                        marginRight: 10
                                                    }}
                                                    layout="inline"
                                                    label="用户角色"
                                                    rules={[
                                                        {
                                                            required: true,
                                                        },
                                                    ]}
                                                >
                                                    <Input placeholder="角色" />
                                                </Form.Item>
                                                <Button
                                                    icon={<IconDelete />}
                                                    shape='circle'
                                                    status='danger'
                                                    style={{
                                                        margin: '0 20px',
                                                    }}
                                                    onClick={() => remove(index)}
                                                ></Button>
                                                <Button
                                                    shape='circle'
                                                    onClick={() => move(index, index > 0 ? index - 1 : index + 1)}
                                                >
                                                    {index > 0 ? <IconArrowRise /> : <IconArrowFall />}
                                                </Button>
                                                <Grid.Col>
                                                    <Form.Item
                                                        field={item.field + '.content'}
                                                        rules={[
                                                            {
                                                                required: true,
                                                                message: "模版内容不能为空"
                                                            },
                                                        ]}
                                                    >
                                                        <EditMarkdown />
                                                    </Form.Item>
                                                </Grid.Col>
                                            </Grid.Row>
                                        );
                                    })}
                                    <Space size={20}>
                                        <Button type="primary"
                                            onClick={() => {
                                                add({ user: "system" });
                                            }}
                                        >
                                            添加
                                        </Button>
                                    </Space>
                                </div>
                            );
                        }}
                    </Form.List>
                </Form.Item>
{/* 
                <Form.Item
                    label="适用AI模型"
                    field="aiModels"
                >
                    <Select
                        mode="multiple"
                        placeholder="选择或输入AI模型"
                        allowCreate
                        onChange={setAiModels}
                        value={aiModels}
                    />
                </Form.Item> */}

                <Form.Item
                    label="分类"
                    field="category"
                    rules={[{ required: true, message: '请选择分类' }]}
                >
                    <Select placeholder="选择分类" allowCreate>
                        <Select.Option value="代码生成">代码生成</Select.Option>
                        <Select.Option value="图像生成">图像生成</Select.Option>
                        <Select.Option value="文案优化">文案优化</Select.Option>
                    </Select>
                </Form.Item>
            </Form>
        </Modal>
    );
}

export default CreateTemplate;